const files = [
  "/app/docs/equipment.md",
  "/app/docs/pumps-and-hydraulics.md",
  "/app/docs/instruments.md",
  "/app/docs/qualification.md",
  "/app/submission/controller.py",
  "/app/runtime/controller_interface.py",
  "/app/public-cases.json",
  "/app/public-acceptance.json",
  "/app/run_case.py"
];
const results = await Promise.allSettled(files.map(async path => {
  const r = await tools.exec_command({cmd:`cat '${path}'`,yield_time_ms:10000,max_output_tokens:20000});
  return {path,output:r.output};
}));
for (const item of results) {
  if (item.status === "fulfilled") text(`--- ${item.value.path} ---\n${item.value.output}`);
  else text(String(item.reason));
}

